package es.cofradia.repertorio.song;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/songs") public class SongController {private final SongService service;public SongController(SongService service){this.service=service;}@GetMapping public List<SongDto.Response> list(){return service.list();}@GetMapping("/{id}") public SongDto.Response get(@PathVariable Long id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public SongDto.Response create(@Valid @RequestBody SongDto.Request request){return service.create(request);}@PutMapping("/{id}") public SongDto.Response update(@PathVariable Long id,@Valid @RequestBody SongDto.Request request){return service.update(id,request);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
